import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
arr = tuple(sorted(int(x) for x in data[1:1 + n]))

@lru_cache(maxsize=None)
def best(t):
    if len(t) == 1:
        return 0
    res = None
    for i in range(len(t)):
        for j in range(i + 1, len(t)):
            s = t[i] + t[j]
            rest = [t[k] for k in range(len(t)) if k != i and k != j] + [s]
            c = s + best(tuple(sorted(rest)))
            if res is None or c < res:
                res = c
    return res

print(best(arr))

